def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize DP tables
    dp1 = [[0] * N for _ in range(N)]
    dp2 = [[0] * N for _ in range(N)]

    # Fill the first path DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp1[i][j] = grid[i][j]
            elif i == 0:
                dp1[i][j] = dp1[i][j-1] + grid[i][j]
            elif j == 0:
                dp1[i][j] = dp1[i-1][j] + grid[i][j]
            else:
                dp1[i][j] = max(dp1[i-1][j], dp1[i][j-1]) + grid[i][j]

    # Fill the second path DP table
    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i == N-1 and j == N-1:
                dp2[i][j] = grid[i][j]
            elif i == N-1:
                dp2[i][j] = dp2[i][j+1] + grid[i][j]
            elif j == N-1:
                dp2[i][j] = dp2[i+1][j] + grid[i][j]
            else:
                dp2[i][j] = max(dp2[i+1][j], dp2[i][j+1]) + grid[i][j]

    # Calculate the maximum sum of values collected on two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            max_sum = max(max_sum, dp1[i][j-1] + dp2[i-1][j])
            max_sum = max(max_sum, dp1[i-1][j-1] + dp2[i][j])

    return max_sum
