def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize counters for aisle effectiveness
    row_effectiveness = [0] * M
    col_effectiveness = [0] * N

    # Count chatting pairs that can be separated by a row aisle
    for Xi, Yi, Pi, Qi in chatting_pairs:
        if Xi == Pi and Yi < Qi <= Yi + 1:
            row_effectiveness[Xi - 1] += 1

    # Count chatting pairs that can be separated by a column aisle
    for Xi, Yi, Pi, Qi in chatting_pairs:
        if Yi == Qi and Xi < Pi <= Xi + 1:
            col_effectiveness[Yi - 1] += 1

    # Select the K most effective rows for aisles
    selected_rows = sorted(range(M), key=lambda i: -row_effectiveness[i])[:K]
    # Select the L most effective columns for aisles
    selected_columns = sorted(range(N), key=lambda i: -col_effectiveness[i])[:L]

    # Return the selected rows and columns as space-separated strings
    return ' '.join(map(str, selected_rows + 1)), ' '.join(map(str, selected_columns + 1))
