from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    if not coeffs:
        return "0"

    terms = []
    for degree in range(n, -1, -1):
        coeff = coeffs[n - degree]
        if coeff == 0:
            continue

        if degree == 0:
            term = str(abs(coeff))
        elif degree == 1:
            if abs(coeff) == 1:
                term = 'x' if coeff == 1 else '-x'
            else:
                term = f'{coeff}x'
        else:
            if abs(coeff) == 1:
                term = f'x^{degree}' if coeff == 1 else f'-x^{degree}'
            else:
                term = f'{coeff}x^{degree}'

        terms.append(term)

    polynomial = terms[0]
    if len(terms) > 1:
        for term in terms[1:]:
            coefficient = term.split('x')[0]
            if coefficient.isdigit():
                polynomial += f'+{term}'
            else:
                polynomial += term

    return polynomial

