    for participant in statements:
        statements[participant] = [stmt for stmt in statements[participant] if not any(day in stmt for day in days_of_week)]

    # Check consistency
    for participant in statements:
        if participant == scenario:
            if participant in liar_count:
                if any(stmt.startswith("I am guilty.") for stmt in statements[participant]):
                    return False
            else:
                if any(stmt.startswith("I am guilty.") for stmt in statements[participant]):
