def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    max_increasing = [1] * n
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            max_increasing[i] = max_increasing[i - 1] + 1

    max_decreasing = [1] * n
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            max_decreasing[i] = max_decreasing[i + 1] + 1

    max_length = 0
    for i in range(n):
        max_length = max(max_length, max_increasing[i] + max_decreasing[i] - 1)

    return n - max_length
```

