def minimum_students_to_leave(heights):
    n = len(heights)
    if n < 3:
        return 0

    dp = [1] * n
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            dp[i] = dp[i - 1] + 1

    min_students = n
    for i in range(n - 2, -1, -1):
        dp[i] = max(dp[i], dp[i + 1] + 1)
        min_students = min(min_students, n - dp[i])

    return min_students
```

